import { createHash } from "node:crypto";
import fs from "node:fs/promises";
import path from "node:path";

/**
 * Faithful fixtures of the layout released before `20261017_task_agent_own_run_v1` (contract §6, §12.3):
 * hand-built JSON in the released record shapes (the frozen `released-trees-before-task-agent-own-run`
 * types), never generated by current code and never copied from user data. A task agent's memory sits
 * inside its coordinating run's folder and its facts are embedded in the coordinating tree.
 *
 * Shapes: F-C1 (agent task agent of a standalone run, rotated traces, context file, snapshot), F-C2 (two task
 * agent teams of the same hub), F-C7 (a task-team member's copy nested in its team record), F-C3 / F-C4
 * (team run), F-C5 / F-C6 (organization root and configured team), F-NS (no `source`: a copy of a configured
 * place), F-ND (no `delegatorAgentRunId`), F-SE (Settings edits on a record and on a team member), F-MSG
 * (messages inside a task team, between hub and team, between task agents), F-UNMATERIALIZED (no folder).
 */

type Json = Record<string, unknown>;
export const T0 = "2026-10-01T08:00:00.000Z";
const at = (minute: number) => `2026-10-01T08:${String(minute).padStart(2, "0")}:00.000Z`;
const launch = { runtimeKind: "codex_app_server", llmModelIdentifier: "gpt-5", llmConfig: { reasoning_effort: "medium" }, autoExecuteTools: true, workspaceRootPath: "/work/project" };
const edit = { llmModelIdentifier: "gpt-5-mini", llmConfig: null, selectedAt: at(30) };
const agentSource = (agentDefinitionId: string) => ({ kind: "agent", agentDefinitionId, launchConfiguration: launch, launchSource: { origin: "agent_default", fallbacks: [] } });
const teamSource = (teamDefinitionId: string, prefix: string, members: string[]) => ({
  kind: "agent_team", teamDefinitionId, coordinatorAddress: `${prefix}/${members[0]}`,
  members: members.map((name, index) => ({ address: `${prefix}/${name}`, agentDefinitionId: name,
    ...(index === 1 ? { launchConfiguration: { ...launch, llmModelIdentifier: "gpt-5-design" }, launchSource: { origin: "agent_default", fallbacks: [] } } : {}) })),
  handoffs: [{ from: `${prefix}/${members[0]}`, to: `${prefix}/${members[1] ?? members[0]}`, rules: ["deliver"] }],
  defaultLaunchConfiguration: launch, defaultLaunchSource: { origin: "team_default", fallbacks: [] },
});
const configuredAgent = (address: string, agentRunId: string, agentDefinitionId: string) => ({
  address, agentDefinitionId, role: null, description: null, agentRunId, platformAgentRunId: null, launchConfiguration: launch,
});
const message = (messageId: string, senderAgentRunId: string, receiverAgentRunId: string, minute: number) => ({
  messageId, senderAgentRunId, receiverAgentRunId, content: `content ${messageId}`, messageType: "agent_message", referenceFiles: [], createdAt: at(minute),
});

const put = async (file: string, value: unknown): Promise<void> => {
  await fs.mkdir(path.dirname(file), { recursive: true });
  await fs.writeFile(file, typeof value === "string" ? value : `${JSON.stringify(value, null, 2)}\n`);
};
const memoryFiles = async (dir: string, name: string, rich = false): Promise<void> => {
  await put(path.join(dir, "raw_traces_active.jsonl"), `${JSON.stringify({ id: `${name}-1`, trace_type: "user", content: `work of ${name}` })}\n`);
  if (!rich) return;
  await put(path.join(dir, "raw_traces_000001.jsonl"), `${JSON.stringify({ id: `${name}-0`, trace_type: "user", content: "rotated" })}\n`);
  await put(path.join(dir, "file_changes.json"), { schemaVersion: 1, entries: [] });
  await put(path.join(dir, "context_files", "ctx_notes__notes.txt"), "context bytes");
  await put(path.join(dir, "working_context_snapshot.json"), { schema_version: 5, messages: [] });
};

