/** Writes the released data root: three coordinating runs with every shape above and their memory. */
export const writeReleasedDataRoot = async (memory: string): Promise<void> => {
  const hub = hubRecords();
  const hubDir = path.join(memory, "agents", "hub");
  await put(path.join(hubDir, "run_metadata.json"), { runId: "hub", agentDefinitionId: "assistant", workspaceRootPath: "/work/project",
    memoryDir: hubDir, llmModelIdentifier: "gpt-5", llmConfig: null, autoExecuteTools: true, runtimeKind: "codex_app_server", platformAgentRunId: null, startedAt: T0 });
  await memoryFiles(hubDir, "hub");
  await put(path.join(hubDir, "collaboration", "collaboration_tree.json"), { subjectKind: "agent", createdAt: T0,
    host: { address: "/assistant", agentRunId: "hub", agentDefinitionId: "assistant" },
    taskExecutions: [hub.c1, hub.c2a, hub.c2b, hub.neverRan] });
  await put(path.join(hubDir, "collaboration", "communication_messages.json"), { schemaVersion: 1, subjectKind: "agent", hostRunId: "hub", messages: HUB_MESSAGES });
  await memoryFiles(path.join(memory, OLD_FOLDERS["c1-reviewer"]!), "c1", true);
  for (const id of ["c2a-lead", "c2a-designer"]) await memoryFiles(path.join(memory, OLD_FOLDERS["c2-team-a"]!, id), id);
  await memoryFiles(path.join(memory, OLD_FOLDERS["c7-helper"]!), "c7");
  await memoryFiles(path.join(memory, OLD_FOLDERS["c2-team-b"]!, "c2b-lead"), "c2b-lead");

  const team = teamRunRecords();
  const teamDir = path.join(memory, "agent_teams", "team-r");
  await put(path.join(teamDir, "team_run_execution_tree.json"), { createdAt: T0, archivedAt: null, applicationBinding: null, handoffs: [],
    rootTeam: { address: "/", teamDefinitionId: "writing-team", teamDefinitionName: "Writing Team", teamRunId: "team-r", coordinatorAddress: "/lead",
      defaultLaunchConfiguration: launch, members: [configuredAgent("/lead", "lead-r", "lead"), configuredAgent("/writer", "writer-r", "writer")],
      taskExecutions: [team.c3, team.nd, team.c4] } });
  await put(path.join(teamDir, "team_communication_messages.json"), { schemaVersion: 1, rootTeamRunId: "team-r", messages: TEAM_RUN_MESSAGES });
  for (const id of ["lead-r", "writer-r"]) await memoryFiles(path.join(teamDir, id), id);
  await memoryFiles(path.join(memory, OLD_FOLDERS["c3-writer-copy"]!), "c3");
  await memoryFiles(path.join(memory, OLD_FOLDERS["nd-copy"]!), "nd");
  await memoryFiles(path.join(memory, OLD_FOLDERS["c4-qa"]!, "c4-qa-lead"), "c4");

  const org = orgRecords();
  const orgDir = path.join(memory, "agent_orgs", "org-o");
  await put(path.join(orgDir, "agent_org_run_execution_tree.json"), { subjectKind: "agent_org", createdAt: T0, archivedAt: null, applicationBinding: null, handoffs: [],
    rootOrg: { address: "/", orgDefinitionId: "company", orgDefinitionName: "Company", orgRunId: "org-o", defaultLaunchConfiguration: launch,
      members: [configuredAgent("/director", "director-o", "director"), { address: "/eng", teamDefinitionId: "eng-team", role: null, description: null,
        teamRunId: "eng-o", coordinatorAddress: "/eng/lead", defaultLaunchConfiguration: launch, members: [configuredAgent("/eng/lead", "eng-lead-o", "lead")],
        taskExecutions: [org.c6] }],
      taskExecutions: [org.c5, org.c5team, org.ns] } });
  await put(path.join(orgDir, "agent_org_communication_messages.json"), { schemaVersion: 1, subjectKind: "agent_org", orgRunId: "org-o", messages: ORG_MESSAGES });
  await memoryFiles(path.join(orgDir, "director-o"), "director");
  await memoryFiles(path.join(orgDir, "eng-o", "eng-lead-o"), "eng-lead");
  for (const id of ["c5-analyst", "ns-director-copy", "c6-helper"]) await memoryFiles(path.join(memory, OLD_FOLDERS[id]!), id);
  await memoryFiles(path.join(memory, OLD_FOLDERS["c5-review"]!, "c5-review-lead"), "c5-review-lead");
};

/** Every file under a folder: relative path → sha256 of its bytes (the memory root's path normalized away). */
export const snapshot = async (root: string, dir = root): Promise<Record<string, string>> => {
  const result: Record<string, string> = {};
  const walk = async (current: string): Promise<void> => {
    for (const entry of await fs.readdir(current, { withFileTypes: true }).catch(() => [])) {
      const full = path.join(current, entry.name);
      if (entry.isDirectory()) await walk(full);
      else result[path.relative(dir, full)] = createHash("sha256").update((await fs.readFile(full, "utf8")).replaceAll(root, "<root>")).digest("hex");
    }
  };
  await walk(dir);
  return result;
};

export type ReleasedJson = Json;
